package com.greenocean.backend;
import com.greenocean.backend.auth.service.*;import com.greenocean.backend.auth.dto.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.*;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.annotation.Transactional;import tools.jackson.databind.ObjectMapper;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
@TestPropertySource(properties={"greenocean.webauthn.enabled=true","greenocean.webauthn.rp-id=example.test","greenocean.webauthn.origins=https://staff.example.test"})
class PhaseEFMfaBoundaryTest {
 @Autowired RegistrationService registration;@Autowired AuthenticationService auth;@Autowired TokenService tokens;@Autowired PrivilegedWebAuthn mfa;@Autowired JdbcTemplate db;@Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired jakarta.persistence.EntityManager entities;@Autowired org.springframework.transaction.PlatformTransactionManager manager;
 String password="A synthetic EF staff passphrase";String email;UUID user;TokenResponse session;
 @BeforeEach void account(){var tx=new org.springframework.transaction.support.TransactionTemplate(manager);tx.setPropagationBehavior(3);tx.executeWithoutResult(s->db.update("DELETE FROM auth_rate_windows"));email="ef-mfa-"+UUID.randomUUID()+"@example.test";registration.register(new RegisterRequest(email,password,null,null,null,"IR",null,null,true,1));user=db.queryForObject("SELECT id FROM users WHERE email=?",UUID.class,email);db.update("UPDATE users SET status='ACTIVE',email_verified=TRUE WHERE id=?",user);entities.clear();}
 void staff(){db.update("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE name='MODERATOR'",user);entities.clear();session=auth.login(new LoginRequest(email,password,null));}
 UUID sid(){return db.queryForObject("SELECT id FROM user_sessions WHERE user_id=?",UUID.class,user);}
 String permit(){String raw=tokens.createRefreshToken();db.update("INSERT INTO webauthn_enrollment_permits(token_hash,user_id,expires_at) VALUES (?,?,CURRENT_TIMESTAMP+INTERVAL '10 minutes')",tokens.hashRefreshToken(raw),user);return raw;}
 @Test @Tag("malicious") void ordinaryUsersCannotEnrollEvenWithARealPasswordSession()throws Exception{session=auth.login(new LoginRequest(email,password,null));mvc.perform(post("/api/v1/auth/mfa/registration/options").header("Authorization","Bearer "+session.accessToken()).contentType("application/json").content("{}")).andExpect(status().isForbidden());assertThat(db.queryForObject("SELECT count(*) FROM webauthn_ceremonies WHERE user_id=?",Integer.class,user)).isZero();}
 @Test @Tag("malicious") void privilegedPasswordAloneDoesNotAuthorizeFirstEnrollmentOrStaffAccess()throws Exception{staff();mvc.perform(post("/api/v1/auth/mfa/registration/options").header("Authorization","Bearer "+session.accessToken()).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(get("/api/v1/admin/dashboard").header("Authorization","Bearer "+session.accessToken())).andExpect(status().isForbidden());assertThat(db.queryForObject("SELECT mfa_authenticated_at IS NULL FROM user_sessions WHERE id=?",Boolean.class,sid())).isTrue();}
 @Test @Tag("happy") void independentPermitCreatesBoundRpUserVerifiedChallengeWithoutGrantingMfa()throws Exception{staff();String proof=permit();var start=mfa.register(user,sid(),proof);assertThat(start.optionsJson()).contains("example.test","required");assertThat(db.queryForObject("SELECT used_at IS NOT NULL FROM webauthn_enrollment_permits WHERE token_hash=?",Boolean.class,tokens.hashRefreshToken(proof))).isTrue();assertThat(db.queryForObject("SELECT session_id FROM webauthn_ceremonies WHERE id=?",UUID.class,start.ceremonyId())).isEqualTo(sid());assertThat(db.queryForObject("SELECT mfa_authenticated_at IS NULL FROM user_sessions WHERE id=?",Boolean.class,sid())).isTrue();assertThatThrownBy(()->mfa.register(user,sid(),proof)).isInstanceOf(com.greenocean.backend.common.exception.ForbiddenException.class);}
 @Test @Tag("confused") void malformedRegistrationConsumesChallengeWithoutInventingAnAuthenticator()throws Exception{staff();var start=mfa.register(user,sid(),permit());assertThatThrownBy(()->mfa.finishRegistration(user,sid(),start.ceremonyId(),"{}","fake")).isInstanceOf(com.greenocean.backend.common.exception.ForbiddenException.class);assertThat(db.queryForObject("SELECT used_at IS NOT NULL FROM webauthn_ceremonies WHERE id=?",Boolean.class,start.ceremonyId())).isTrue();assertThat(db.queryForObject("SELECT count(*) FROM webauthn_credentials WHERE user_id=?",Integer.class,user)).isZero();}
 @Test @Tag("malicious") void expiredAndSubstitutedCeremoniesCannotBeUsed()throws Exception{staff();var start=mfa.register(user,sid(),permit());assertThatThrownBy(()->mfa.finishRegistration(user,sid(),UUID.randomUUID(),"{}","fake")).isInstanceOf(com.greenocean.backend.common.exception.ForbiddenException.class);db.update("UPDATE webauthn_ceremonies SET expires_at=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE id=?",start.ceremonyId());assertThatThrownBy(()->mfa.finishRegistration(user,sid(),start.ceremonyId(),"{}","fake")).isInstanceOf(com.greenocean.backend.common.exception.ForbiddenException.class);}
}
